package com.company.iaf.qms.engineering.interfaces.controller;
import com.company.iaf.qms.engineering.infrastructure.persistence.ValidationPlanService;import com.company.iaf.qms.engineering.interfaces.dto.*;import com.company.iaf.shared.result.Result;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/qms/inspection-standards/{inspectionStandardId}/validation-plan") public class QmsValidationPlanController{private final ValidationPlanService service;public QmsValidationPlanController(ValidationPlanService service){this.service=service;}@GetMapping public Result<ValidationPlanResponse> get(@PathVariable long inspectionStandardId){return Result.ok(service.get(QmsRequestContext.tenantId(),QmsRequestContext.orgId(),inspectionStandardId));}@PostMapping("/generate") public Result<ValidationPlanResponse> generate(@PathVariable long inspectionStandardId){return Result.ok(service.generate(QmsRequestContext.tenantId(),QmsRequestContext.orgId(),inspectionStandardId));}@PutMapping("/{id}") public Result<ValidationPlanResponse> update(@PathVariable long inspectionStandardId,@PathVariable long id,@Valid @RequestBody ValidationPlanUpdateRequest q){return Result.ok(service.update(QmsRequestContext.tenantId(),QmsRequestContext.orgId(),inspectionStandardId,id,q));}@PostMapping("/{id}/submit-approval") public Result<ValidationPlanResponse> submit(@PathVariable long inspectionStandardId,@PathVariable long id,@Valid @RequestBody ValidationPlanActionRequest q){return Result.ok(service.submit(QmsRequestContext.tenantId(),QmsRequestContext.orgId(),inspectionStandardId,id,q.comment()));}@PostMapping("/{id}/approve") public Result<ValidationPlanResponse> approve(@PathVariable long inspectionStandardId,@PathVariable long id,@Valid @RequestBody ValidationPlanActionRequest q){return Result.ok(service.approve(QmsRequestContext.tenantId(),QmsRequestContext.orgId(),inspectionStandardId,id,q.comment()));}@PostMapping("/{id}/reject") public Result<ValidationPlanResponse> reject(@PathVariable long inspectionStandardId,@PathVariable long id,@Valid @RequestBody ValidationPlanActionRequest q){return Result.ok(service.reject(QmsRequestContext.tenantId(),QmsRequestContext.orgId(),inspectionStandardId,id,q.comment()));}@PostMapping("/{id}/release") public Result<ValidationPlanResponse> release(@PathVariable long inspectionStandardId,@PathVariable long id,@Valid @RequestBody ValidationPlanActionRequest q){return Result.ok(service.release(QmsRequestContext.tenantId(),QmsRequestContext.orgId(),inspectionStandardId,id,q.comment()));}}
